'use strict';
let lessonIndex=-1, lessonStep=0, examView=null, examStep=0;
const STEP_NAMES=['먼저 풀어보기','설명 읽기','연습하기','직접 쓰고 고치기','다시 풀고 정리하기'];
const stamp=()=>new Date().toISOString();
function learningState(){
 if(saved.learningV3 && saved.learningV3.version!==LEARNING_VERSION){saved.learningArchives=saved.learningArchives||[];saved.learningArchives.push(saved.learningV3);delete saved.learningV3;}
 if(!saved.learningV3){saved.learningV3={version:LEARNING_VERSION,created:stamp(),order:Math.random()<.5?['A','B']:['B','A'],lessons:{},assessments:{},exposures:[],events:[]};persist();}
 return saved.learningV3;
}
function logLearning(type,detail={}){const s=learningState();s.events.push({at:stamp(),type,...detail});persist();}
function lessonRecord(i=lessonIndex){const s=learningState();return s.lessons[i]||(s.lessons[i]={started:stamp(),step:0,answers:{},fields:{},evidence:['','',''],history:[]});}
function focusLearning(){window.scrollTo({top:0,behavior:'instant'});const h=$('#learning-heading');if(h)h.focus();}
function changeStep(n){lessonStep=n;lessonRecord().step=n;persist();renderCourse();focusLearning();}
function launchLesson(i){
 const s=learningState();if(!s.assessments.pre?.submitted&&!s.preDecision){s.preDecision={at:stamp(),choice:'skipped'};}
 lessonIndex=i;lessonStep=lessonRecord(i).step||0;page='course';logLearning('lesson-open',{lesson:i+1});render();focusLearning();
}
function firstCorrect(rec,q){return rec?.attempts?.[0]?.choice===q.key;}
function latestCorrect(rec,q){return rec?.attempts?.at(-1)?.choice===q.key;}
function questionMarkup(q,record,mode='learn',optionOrder=[0,1,2]){
 const attempt=record?.attempts?.at(-1);return `<fieldset class="question"><legend>${esc(q.stem)}</legend><p class="note">${mode==='learn'?'연습을 위해 만든 문제입니다.':'해설을 보지 않고, 가장 적절한 답 하나를 골라 주세요.'}</p>${optionOrder.map(k=>{const o=q.options[k];return `<label class="answer-option"><input type="radio" name="${q.id}" data-answer="${q.id}" value="${k}" ${record?.selected===k?'checked':''}><span>${esc(o)}</span></label>`}).join('')}</fieldset>${mode==='learn'?`<button class="primary" id="submit-choice">정답과 해설 확인</button>${attempt?`<section id="choice-feedback" tabindex="-1" class="feedback ${attempt.choice===q.key?'':'warning'}" role="status"><h3>${attempt.choice===q.key?'정답입니다.':'해설을 읽고 다시 풀어 보세요.'}</h3><p>${esc(q.feedback[attempt.choice])}</p><p>${esc(q.why)}</p><p class="note">처음 고른 답: ${record.attempts[0].choice===q.key?'정답':'오답'} · 총 ${record.attempts.length}회 풀이. 다시 풀어도 처음 고른 답은 따로 저장됩니다.</p></section>`:''}`:''}`;
}
function bindPractice(q,rec){
 document.querySelectorAll('[data-answer]').forEach(el=>el.onchange=()=>{rec.selected=Number(el.value);persist();});
 $('#submit-choice').onclick=()=>{if(!Number.isInteger(rec.selected)){notify('답을 하나 골라 주세요.');return;}
 rec.attempts=rec.attempts||[];if(rec.attempts.at(-1)?.choice===rec.selected){notify('같은 답에 대한 설명은 아래에서 확인할 수 있습니다.');return;}
 rec.attempts.push({choice:rec.selected,at:stamp()});persist();renderCourse();$('#choice-feedback')?.focus();};
}
function renderCourse(){
 const s=learningState();if(lessonIndex<0){renderLearningHome();return;}
 const c=COURSE[lessonIndex],r=lessonRecord(),qs=PRACTICE[lessonIndex],q=qs[lessonStep===0?0:lessonStep===2?1:2];
 $('#main').innerHTML=`<div class="learning-shell"><div class="section-title"><button id="back-course">← 전체 과정</button><span class="save-status" id="save-state" role="status">${storageOK?'이 기기에 저장됨':'저장 제한 · 백업 필요'}</span></div><p class="eyebrow">${lessonIndex+1}차시 / 8 · 약 20분 · ${esc(c.phase)}</p><h1 id="learning-heading" tabindex="-1">${esc(c.title)}</h1><ol class="learning-steps" aria-label="차시 진행">${STEP_NAMES.map((v,i)=>`<li ${i===lessonStep?'aria-current="step"':''}>${i+1}. ${v}</li>`).join('')}</ol><p class="note">한 차시에는 약 20분이 걸립니다. 시간 제한은 없고, 중간에 멈춰도 이어서 할 수 있습니다.</p><div id="learning-body" class="card"></div><div class="lesson-nav"><button id="lesson-prev" ${lessonStep===0?'disabled':''}>이전 단계</button><span>${lessonStep+1} / 5</span><button id="lesson-next" class="primary">${lessonStep===4?'정리하고 마치기':'다음 단계 →'}</button></div></div>`;
 $('#back-course').onclick=()=>{lessonIndex=-1;renderCourse();focusLearning();};$('#lesson-prev').onclick=()=>changeStep(lessonStep-1);
 const body=$('#learning-body');
 if(lessonStep===0||lessonStep===2||lessonStep===4){const rec=r.answers[q.id]||(r.answers[q.id]={});body.innerHTML=`<span class="tag">${lessonStep===0?'설명을 읽기 전에':lessonStep===2?'답을 고르고 해설 확인하기':'배운 내용 확인하기'}</span><h2>${lessonStep===0?'설명을 읽기 전에 먼저 풀어 보세요':lessonStep===2?'답을 고른 뒤 해설을 읽어 보세요':'다른 상황에서도 풀 수 있을까요?'}</h2>${lessonStep===0&&lessonIndex===7?'<p>앞 차시를 마친 뒤 3~7일 정도 지나서 풀어 보세요. 이전 답을 보지 않고 얼마나 기억하는지 확인하는 연습입니다. 원하면 지금 바로 진행해도 됩니다.</p>':''}${questionMarkup(q,rec)}${lessonStep===4?`<label class="field" for="takeaway">다음에 AI에게 요청할 때 무엇을 확인하겠나요?</label><textarea id="takeaway" maxlength="3000" placeholder="예: 예시의 말투가 요구와 맞는지 먼저 확인하겠어요.">${esc(r.fields.takeaway||'')}</textarea><p class="note">여기서는 이번 차시에서 배운 내용을 복습합니다. 학습 전후의 변화를 비교하려면 ‘배움 확인’의 평가를 이용하세요.</p>`:''}`;
 bindPractice(q,rec);if($('#takeaway'))$('#takeaway').oninput=e=>saveLessonField('takeaway',e.target.value);
 }else if(lessonStep===1){body.innerHTML=`<span class="tag">핵심 질문</span><h2>${esc(c.question)}</h2>${c.lesson.map(t=>`<p>${esc(t)}</p>`).join('')}<div class="worked-example"><p class="note">설명을 위해 만든 예시입니다.</p><h3>${esc(WORKED[lessonIndex].title)}</h3><pre class="response">${esc(WORKED[lessonIndex].before)}</pre>${WORKED[lessonIndex].after?`<h4>검토 후</h4><pre class="response">${esc(WORKED[lessonIndex].after)}</pre>`:""}<ol>${WORKED[lessonIndex].steps.map(t=>`<li>${esc(t)}</li>`).join("")}</ol></div><h3>답안을 쓴 뒤 확인할 세 가지</h3><ul>${c.checks.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>${c.caseIndex!==null?`<details><summary>관련 실험의 실제 응답과 전체 결과 보기</summary>${courseEvidence(c.caseIndex)}</details>`:'<div class="result">이 차시에서는 논문에서 다루지 않은 형식으로 연습합니다. 이 형식에서도 같은 효과가 나타나는지는 아직 확인하지 않았습니다.</div>'}<p class="note">논문은 프롬프트에 따른 응답 차이를 연구했습니다. 이 앱으로 얼마나 배울 수 있는지는 별도로 확인해야 합니다.</p>`;
 }else renderArtifact(body,c,r);
 $('#lesson-next').onclick=()=>{
 if([0,2,4].includes(lessonStep)&&!r.answers[q.id]?.attempts?.length){notify('답을 고르고 정답과 해설을 확인해 주세요. 틀려도 다음 단계로 갈 수 있습니다.');return;}
 if(lessonStep===3&&!r.history.length){notify('초안과 검토 근거를 남기고 ‘수정 기록 저장’을 눌러 주세요.');return;}
 if(lessonStep===3&&r.dirty){notify('바꾼 답안을 먼저 저장해 주세요.');return;}
 if(lessonStep<4){changeStep(lessonStep+1);return;}
 if(!r.fields.takeaway?.trim()){notify('다음에 AI에게 요청할 때 확인할 점을 한 줄 적어 주세요.');return;}
 r.completed=stamp();r.reviewNeeded=!firstCorrect(r.answers[qs[2].id],qs[2]);persist();renderLessonSummary();focusLearning();
 };
}
function saveLessonField(k,v){const r=lessonRecord();r.fields[k]=v;if(k!=='takeaway')r.dirty=true;const ok=persist();const el=$('#save-state');if(el)el.textContent=ok?'자동 저장됨':'저장 제한 · 전체 과정에서 백업 필요';}
function renderArtifact(body,c,r){
 body.innerHTML=`<span class="tag">직접 작성하기 · 자동 채점하지 않습니다</span><h2>직접 써 보고, 조건에 맞게 고쳐 보세요</h2><div class="task-brief">${esc(c.task)}</div>${r.draftLocked?`<details><summary>처음 쓴 답안 보기</summary><pre class="response">${esc(r.firstDraft)}</pre></details>`:`<label class="field" for="artifact-draft">초안 · ${esc(c.prompts.join(' '))}</label><textarea id="artifact-draft" maxlength="12000" class="large">${esc(r.fields.draft||'')}</textarea><button id="lock-draft">초안 저장하고 검토하기</button><p class="note">먼저 스스로 답을 써 보세요. 저장한 뒤 해설을 읽고 비교할 수 있습니다. 직접 쓴 답안은 자동 채점하지 않습니다.</p>`}<div id="artifact-review" tabindex="-1"></div>`;
 if(!r.draftLocked){$('#artifact-draft').oninput=e=>saveLessonField('draft',e.target.value);$('#lock-draft').onclick=()=>{const t=r.fields.draft?.trim();if(!t){notify('초안을 먼저 작성해 주세요.');return;}r.firstDraft=t;r.draftLocked=stamp();persist();renderCourse();$('#artifact-review').focus();};return;}
 $('#artifact-review').innerHTML=`<details id="worked-solution"><summary>예시 답안과 해설</summary><p>${esc(c.example)}</p></details><label class="field" for="artifact-final">검토 후 답안</label><textarea id="artifact-final" maxlength="12000" class="large" placeholder="요구한 조건을 지키면서, 필요한 부분만 고쳐 보세요.">${esc(r.fields.final||'')}</textarea><h3>각 조건을 지킨 부분을 답안에서 찾아 적으세요</h3><p class="note">아래 조건에 해당하는 문장이나 계산을 답안에서 찾아 옮겨 적어 주세요. 실제로 조건에 맞는지는 직접 확인하거나 다른 사람에게 검토를 부탁하세요.</p>${c.checks.map((t,i)=>`<label class="field" for="evidence-${i}">${i+1}. ${esc(t)}</label><textarea id="evidence-${i}" data-evidence="${i}" maxlength="3000" placeholder="조건에 맞는 부분을 옮겨 적고, 왜 맞는지 설명해 주세요.">${esc(r.evidence[i]||'')}</textarea>`).join('')}<label class="field" for="artifact-reason">어디를 고쳤고, 왜 고쳤나요? 고치지 않았다면 그 이유를 적어 주세요.</label><textarea id="artifact-reason" maxlength="3000">${esc(r.fields.reason||'')}</textarea><button id="save-artifact" class="primary">수정 기록 저장</button><div id="artifact-message" role="status">${r.history.length?`<p>수정 기록 ${r.history.length}개 저장됨 · 답안이 맞는지는 직접 검토해 주세요.</p>`:''}</div><details><summary>추가 문제 · 선택</summary><p>${esc(c.extra)}</p></details>`;
 $('#worked-solution').ontoggle=e=>{if(e.target.open&&!r.solutionViewed){r.solutionViewed=stamp();persist();}};
 $('#artifact-final').oninput=e=>saveLessonField('final',e.target.value);$('#artifact-reason').oninput=e=>saveLessonField('reason',e.target.value);
 document.querySelectorAll('[data-evidence]').forEach(el=>el.oninput=()=>{r.evidence[Number(el.dataset.evidence)]=el.value;r.dirty=true;persist();});
 $('#save-artifact').onclick=()=>{if(!r.fields.final?.trim()||!r.fields.reason?.trim()||r.evidence.some(t=>!t.trim())){notify('고친 답안, 세 조건을 지킨 근거, 수정한 이유를 모두 적어 주세요.');return;}
 r.history.push({at:stamp(),final:r.fields.final,reason:r.fields.reason,evidence:[...r.evidence]});r.dirty=false;persist();$('#artifact-message').innerHTML='<p class="result">작성한 답안과 검토 내용을 저장했습니다. 다음 단계에서는 다른 문제를 풀어 보세요. 저장했다고 해서 정답으로 처리되지는 않습니다.</p>';};
}
function renderLessonSummary(){const c=COURSE[lessonIndex],r=lessonRecord(),qs=PRACTICE[lessonIndex];$('#main').innerHTML=`<div class="learning-shell card"><p class="eyebrow">${lessonIndex+1}차시 활동 기록</p><h1 id="learning-heading" tabindex="-1">${r.reviewNeeded?'마지막 문제를 한 번 더 살펴보세요':'이번 차시를 마쳤습니다'}</h1><p>마지막 문제에서 처음 고른 답은 ${r.reviewNeeded?'틀렸습니다. 해설을 읽고 다시 풀 수 있습니다. 처음 고른 답과 다시 푼 답은 따로 저장합니다.':'맞았습니다. 직접 작성한 답안도 조건에 맞는지 확인해 보세요. 한 문제를 맞힌 것만으로 충분히 익혔다고 판단하지는 않습니다.'}</p><div class="result"><h3>내가 기억할 점</h3><p>${esc(r.fields.takeaway)}</p></div><h3>복습할 때 기억할 점</h3><p>${esc(qs[2].why)}</p><p>오늘은 여기서 멈춰도 됩니다. 다음 차시는 다른 날 이어가 보세요. 마지막 평가에서는 해설 없이 새 과제를 풀게 됩니다.</p><div class="actions"><button id="summary-home">전체 과정</button><button id="summary-review">새 상황 문제 다시 보기</button>${lessonIndex<7?'<button id="summary-next">다음 차시 살펴보기</button>':'<button id="summary-assess" class="primary">사후 평가로 이동</button>'}</div></div>`;
 $('#summary-home').onclick=()=>{lessonIndex=-1;renderCourse();};$('#summary-review').onclick=()=>changeStep(4);if($('#summary-next'))$('#summary-next').onclick=()=>launchLesson(lessonIndex+1);if($('#summary-assess'))$('#summary-assess').onclick=()=>go('assessment');}
function renderLearningHome(){const s=learningState(),count=Object.values(s.lessons).filter(r=>r.completed).length;$('#main').innerHTML=`<section class="hero"><div><p class="eyebrow">프롬프트 작성 연습</p><h1 id="learning-heading" tabindex="-1">AI가 조건을 놓쳤다면,<br>프롬프트부터 살펴보세요.</h1><p>문장 수나 말투를 정해 줬는데도 AI가 지키지 않았나요? 먼저 응답에서 확인할 조건을 정합니다. 그 조건을 전달할 방법을 고른 뒤, 실제 응답이 조건을 지켰는지 확인하는 연습을 합니다. 이 과정은 글의 형식과 지시 준수에 집중합니다.</p></div><div class="hero-aside"><strong>${count}/8</strong><small>마친 차시</small></div></section><div class="card"><h2>하루 한 차시, 약 20분</h2><p>먼저 문제를 풀고, 설명을 읽은 뒤 직접 프롬프트를 작성합니다. 지시만으로 시작하는 경우와 예시·빈 틀이 필요한 경우를 비교하고, 마지막에는 자신의 작업에 적용합니다.</p><p class="note">20분은 예상 시간입니다. 작성한 답과 진행 단계는 자동 저장됩니다.</p><div class="actions"><button id="resume-learning" class="primary">${count===8?'1차시 다시 살펴보기':Object.keys(s.lessons).length?'이어서 학습':'학습 시작'}</button><button id="assess-from-home">학습 전후 평가</button></div></div>${!s.assessments.pre?.submitted?'<div class="guide"><h2>배우기 전에는 얼마나 알고 있을까요?</h2><p>배우기 전과 후를 비교하고 싶다면 사전 평가부터 풀어 보세요. 객관식 6문항과 직접 작성하는 1문항으로, 약 10~15분이 걸릴 것으로 예상합니다. 바로 학습을 시작해도 괜찮지만, 이후에 치른 평가는 학습 전 실력과 구분해야 합니다.</p><button id="baseline-start">사전 평가 먼저 하기</button></div>':''}<div class="course-grid">${COURSE.map((c,i)=>{const r=s.lessons[i];return `<button class="course-card" data-lesson="${i}"><span class="tag">${i+1}차시 · 약 20분</span><h2>${esc(c.title)}</h2><p>${esc(c.question)}</p><strong>${r?.completed?(r.reviewNeeded?'완료 · 복습 필요':'완료'):r?'진행 중 · '+STEP_NAMES[r.step||0]:'시작 전'}</strong><p class="note">${i>=6?'새로운 형식으로 연습하기 · 실제 효과는 별도 확인':esc(c.phase)}</p></button>`}).join('')}</div><section class="card"><h2>답안과 수정 과정을 저장합니다</h2><p>과제가 바뀌어 이번 과정은 새로 시작합니다. 이전 과정의 기록은 전체 백업 파일에 남아 있습니다.</p><p>처음 고른 답과 다시 푼 답, 초안과 수정 이유를 따로 저장합니다. 직접 쓴 답안은 자동 채점하지 않습니다. 얼마나 배웠는지는 새로운 문제를 풀고, 작성한 답안을 다른 사람에게 검토받아 확인해 보세요.</p><div class="actions"><button id="backup-v3">전체 기록 백업</button><label class="import-label">학습 백업 불러오기<input id="restore-v3" type="file" accept=".json,application/json"></label></div><p class="note">이 기기의 브라우저에 저장됩니다. 파일 위치나 브라우저를 바꿀 때는 먼저 백업하세요. 새 과정 복원은 이 버전의 기록만 교체하며 이전 과정 기록은 보존합니다.</p>${saved.course20||saved.course?'<details><summary>개편 전 과정 기록</summary><p>과제가 바뀌어 새 과정의 답안으로 옮기지 않았습니다. 전체 기록 백업에 원래 기록이 포함됩니다.</p></details>':''}</section>`;
 $('#resume-learning').onclick=()=>launchLesson(Math.max(0,COURSE.findIndex((_,i)=>!s.lessons[i]?.completed)));
 $('#assess-from-home').onclick=()=>go('assessment');if($('#baseline-start'))$('#baseline-start').onclick=()=>{page='assessment';beginExam('pre');};
 document.querySelectorAll('[data-lesson]').forEach(el=>el.onclick=()=>launchLesson(Number(el.dataset.lesson)));
 $('#backup-v3').onclick=exportBackup;$('#restore-v3').onchange=restoreBackup;
}
function examForm(kind,s=learningState()){return kind==='delayed'?'C':s.order[kind==='pre'?0:1];}
function shuffledOptions(){const a=[0,1,2];for(let i=2;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function examScore(e){return e?.submitted?EXAMS[e.form].reduce((n,q)=>n+(e.answers[q.id]===q.key?1:0),0):null;}
function contamination(kind){const s=learningState();const labels=[];
 if(kind==='pre'&&(Object.keys(s.lessons).length||Object.keys(saved.course20||{}).length||Object.keys(saved.course||{}).length||Object.keys(saved.cases||{}).length||saved.draft))labels.push('학습·연습 기록 있음');
 if(kind==='pre'&&s.events.some(e=>e.type==='reference-open'))labels.push('사전 평가 전에 연구·연습 화면 열람');
 const started=s.assessments[kind]?.started;if(started&&s.events.some(e=>['reference-open','lesson-open'].includes(e.type)&&Date.parse(e.at)>=Date.parse(started)))labels.push('평가 시작 후 학습 자료 열람');
 if(s.exposures.length)labels.push('평가 해설을 미리 열었음');return labels;
}
function beginExam(kind){const s=learningState();if(s.assessments[kind]?.submitted){notify('제출한 평가 답안은 변경하지 않습니다. 결과에서 확인하세요.');return;}
 if(kind==='delayed'&&!s.assessments.post?.submitted){notify('사후 평가를 먼저 제출해 주세요.');return;}
 const e=s.assessments[kind]||(s.assessments[kind]={form:examForm(kind),started:stamp(),answers:{},artifact:'',step:0,flags:contamination(kind)});
 if(!e.optionOrders)e.optionOrders=Object.fromEntries(EXAMS[e.form].map(q=>[q.id,shuffledOptions()]));
 if(kind==='pre')s.preDecision={at:stamp(),choice:'assessment'};examView=kind;examStep=e.step||0;page='assessment';persist();render();focusLearning();
}
function renderAssessment(){if(examView){renderExam();return;}const s=learningState(),pre=s.assessments.pre,post=s.assessments.post,delayed=s.assessments.delayed;
 $('#main').innerHTML=`<div class="learning-shell"><p class="eyebrow">배움 확인 · 학습 전후 비교</p><h1 id="learning-heading" tabindex="-1">배운 내용을<br>새 문제에도 적용할 수 있을까요?</h1><p>학습 전과 후, 그리고 며칠 뒤에 새로운 문제를 풀어 보세요. 점수가 어떻게 달라졌는지 비교할 수 있습니다. 다만 그 차이가 이 앱 덕분인지는 이 기록만으로 알 수 없습니다.</p><div class="card"><h2>평가 방법</h2><p>평가마다 객관식 6문항과 직접 작성하는 1문항이 있습니다. 학습 시간과 별도로 약 10~15분을 예상해 주세요. 제출한 답안은 고칠 수 없고, 정답과 해설은 원할 때 직접 열어 볼 수 있습니다.</p><p class="note">A/B형 순서는 이 기록에서 ${s.order.join(' → ')}로 배정됐습니다. 비슷한 내용을 묻도록 만들었지만, 난이도가 같은지는 아직 확인하지 않았습니다. 각 영역에 한 문제씩만 있으므로 점수는 참고용으로 봐 주세요. C형은 며칠 뒤 다시 확인할 때 사용합니다.</p><div class="assessment-grid">${['pre','post','delayed'].map((k,i)=>{const e=s.assessments[k],disabled=k==='delayed'&&!post?.submitted;return `<section class="assessment-card"><h3>${['학습 전','과정 후','며칠 뒤'][i]}</h3><p>${['배우기 전 확인','새 요구에 적용','3~7일 뒤 권장'][i]}</p>${e?.submitted?`<strong>객관식 ${examScore(e)} / 6</strong><p>직접 쓴 답안은 별도 검토가 필요합니다.</p><p class="note">제출 ${esc(new Date(e.submitted).toLocaleDateString('ko-KR'))}</p>`:`<button data-exam="${k}" ${disabled?'disabled':''}>${e?'이어서 응시':'평가 시작'}</button>`}</section>`}).join('')}</div>${pre?.submitted&&post?.submitted?`<div class="result"><strong>객관식 변화: ${examScore(post)-examScore(pre)>0?'+':''}${examScore(post)-examScore(pre)}점 / 6점</strong><p>문제 수가 적고 평가마다 과제가 다릅니다. 문제에 익숙해졌거나 다른 곳에서 배운 내용도 점수에 영향을 줄 수 있습니다. 직접 쓴 답안이 얼마나 나아졌는지는 따로 검토해야 합니다.</p></div>`:''}${post?.submitted?`<p class="note">사후 제출 이후 ${Math.max(0,Math.floor((Date.now()-Date.parse(post.submitted))/86400000))}일 경과. 지연 평가는 3~7일 뒤를 권장하며 일찍 진행해도 실제 간격을 기록합니다.</p>`:''}</div><section class="card"><h2>결과를 볼 때 알아둘 점</h2><p>아직 실제 학습자를 대상으로 이 앱의 효과를 확인하지 않았습니다. 여기서는 그 확인에 필요한 답안과 점수를 모읍니다. 객관식 점수, 직접 쓴 답안, 며칠 뒤의 결과를 각각 살펴보세요.</p>${assessmentTable(s)}<div class="actions"><button id="export-study">평가 기록 JSON</button><button id="export-study-csv">객관식 문항별 CSV</button><button id="export-review">작성 답안·채점표</button></div><p class="note">서술 답안에 개인정보를 적지 마세요. 파일은 사용자가 직접 공유하며 앱은 전송하지 않습니다. 자기평가와 독립 평가를 구분하세요.</p></section><section class="card"><h2>해설은 언제 보는 게 좋을까요?</h2><p>며칠 뒤 평가까지 마친 다음에 해설을 보는 것을 권합니다. 먼저 해설을 열면 이후 답에 영향을 줄 수 있어, 그 사실을 기록합니다. 평가 중 다른 자료나 도움을 이용했는지도 제출할 때 알려 주세요.</p><button id="reveal-exams">제출한 평가의 답안·해설 열기</button><div id="exam-solutions"></div></section><section id="ratings-panel" class="card"></section></div>`;
 renderRatings();document.querySelectorAll('[data-exam]').forEach(el=>el.onclick=()=>beginExam(el.dataset.exam));
 $('#export-study').onclick=()=>download('prompt-lab-assessment.json',JSON.stringify(studyExport(),null,2),'application/json');
 $('#export-study-csv').onclick=()=>download('prompt-lab-assessment-items.csv','\uFEFF'+studyCSV(),'text/csv;charset=utf-8');
 $('#export-review').onclick=()=>download('prompt-lab-independent-review.md',reviewPacket());
 $('#reveal-exams').onclick=()=>{if(!Object.values(s.assessments).some(e=>e.submitted)){notify('제출한 평가가 없습니다.');return;}if(!s.assessments.delayed?.submitted&&!confirm('지연 평가 전 해설을 열면 이후 점수가 영향을 받을 수 있습니다. 해설 노출을 기록하고 열까요?'))return;
 s.exposures.push({at:stamp(),forms:Object.values(s.assessments).filter(e=>e.submitted).map(e=>e.form)});persist();$('#exam-solutions').innerHTML=Object.entries(s.assessments).filter(([,e])=>e.submitted).map(([kind,e])=>`<h3>${{pre:'사전',post:'사후',delayed:'지연'}[kind]} · ${e.form}형</h3>${EXAMS[e.form].map(q=>`<article class="feedback"><h4>${esc(q.stem)}</h4><p>내 답: ${esc(q.options[e.answers[q.id]])}</p><p><strong>정답: ${esc(q.options[q.key])}</strong></p><p>${esc(q.why)}</p></article>`).join('')}<h4>직접 설계 답안</h4><pre class="response">${esc(e.artifact)}</pre>`).join('');};
}
function assessmentTable(s){return `<div class="tablewrap"><table><caption>항목별 결과</caption><thead><tr><th>능력</th><th>사전 첫 제출</th><th>사후 첫 제출</th><th>지연 첫 제출</th></tr></thead><tbody>${SKILLS.map((sk,i)=>`<tr><th>${sk}</th>${['pre','post','delayed'].map(k=>{const e=s.assessments[k];return `<td>${e?.submitted?(e.answers[EXAMS[e.form][i].id]===EXAMS[e.form][i].key?'일치':'재검토 필요'):'미측정'}</td>`}).join('')}</tr>`).join('')}</tbody></table></div>${Object.entries(s.assessments).filter(([,e])=>e.submitted).map(([k,e])=>`<p class="note">${{pre:'사전',post:'사후',delayed:'지연'}[k]} 해석 조건: ${esc([...e.flags,...(e.help==='yes'?['외부 도움 사용']:e.help==='unknown'?['외부 도움 불확실']:[]),...(e.kind==='post'&&e.lessonsCompleted<8?['과정 일부만 진행']:[])].join(' · ')||'기록된 참고 사항 없음 · 다른 영향까지 통제한 평가는 아닙니다.')} ${e.delayDays!==undefined?'· 사후와의 간격 '+e.delayDays.toFixed(1)+'일':''}</p>`).join('')}`;}
function renderExam(){const s=learningState(),e=s.assessments[examView],qs=EXAMS[e.form],q=qs[examStep];
 $('#main').innerHTML=`<div class="learning-shell"><div class="section-title"><button id="exit-exam">저장하고 평가 목록으로</button><span class="note">답안 자동 저장 · 제출 전 수정 가능</span></div><p class="eyebrow">${{pre:'사전',post:'사후',delayed:'지연'}[examView]} 평가 · ${e.form}형</p><h1 id="learning-heading" tabindex="-1">${examStep<6?`${examStep+1} / 6 · 판단 문제`:'직접 설계 · 마지막 과제'}</h1><div class="card">${q?questionMarkup(q,{selected:e.answers[q.id]},'exam',e.optionOrders?.[q.id]||[0,1,2]):`<div class="task-brief">${esc(PRODUCTIONS[e.form])}</div><p>지금 할 수 있는 만큼 작성하세요. 평가 중에는 학습 해설과 이전 답을 보지 않는 것을 권장합니다.</p><label class="field" for="exam-artifact">직접 작성한 답안</label><textarea id="exam-artifact" class="large" maxlength="12000">${esc(e.artifact)}</textarea><fieldset><legend>문제를 풀면서 이전 답이나 해설을 봤거나, AI나 다른 사람의 도움을 받았나요?</legend>${[['no','사용하지 않았어요'],['yes','사용했어요'],['unknown','잘 모르겠어요']].map(([v,t])=>`<label class="answer-option"><input name="exam-help" type="radio" data-help="${v}" ${e.help===v?'checked':''}>${t}</label>`).join('')}</fieldset><p class="note">직접 쓴 답안은 저장만 하고 자동으로 채점하지 않습니다. 모든 문제에 답했는지 확인한 뒤 제출해 주세요. 제출 후에는 답안을 고칠 수 없습니다.</p>`}</div><div class="lesson-nav"><button id="exam-prev" ${examStep===0?'disabled':''}>이전</button><span>${examStep+1} / 7</span><button class="primary" id="exam-next">${examStep===6?'최종 제출':'다음'}</button></div></div>`;
 $('#exit-exam').onclick=()=>{examView=null;renderAssessment();};document.querySelectorAll('[data-answer]').forEach(el=>el.onchange=()=>{e.answers[q.id]=Number(el.value);persist();});
 if($('#exam-artifact'))$('#exam-artifact').oninput=ev=>{e.artifact=ev.target.value;persist();};document.querySelectorAll('[data-help]').forEach(el=>el.onchange=()=>{e.help=el.dataset.help;persist();});
 $('#exam-prev').onclick=()=>{examStep--;e.step=examStep;persist();renderExam();focusLearning();};
 $('#exam-next').onclick=()=>{if(examStep<6){if(!Number.isInteger(e.answers[q.id])){notify('답을 하나 선택해 주세요.');return;}examStep++;e.step=examStep;persist();renderExam();focusLearning();return;}
 const error=examSubmissionError(e);if(error){notify(error);return;}if(!confirm('첫 제출 답안으로 잠급니다. 이후에는 고칠 수 없습니다. 제출할까요?'))return;
 submitExam(examView);examView=null;renderAssessment();focusLearning();};
}
function examSubmissionError(e){if(EXAMS[e.form].some(q=>!Number.isInteger(e.answers[q.id])||e.answers[q.id]<0||e.answers[q.id]>=q.options.length))return '객관식 여섯 문항에 모두 답해 주세요.';if(!e.artifact.trim())return '직접 설계 답안을 적어 주세요. 어렵다면 막힌 부분을 기록해도 됩니다.';if(!['yes','no','unknown'].includes(e.help))return '도움 사용 여부를 선택해 주세요.';return '';}
function submitExam(kind){const s=learningState(),e=s.assessments[kind];if(!e||e.submitted||examSubmissionError(e))return false;
 e.kind=kind;e.submitted=stamp();e.lessonsCompleted=Object.values(s.lessons).filter(r=>r.completed).length;e.flags=[...new Set([...e.flags,...contamination(kind)])];
 if(kind==='delayed')e.delayDays=(Date.parse(e.submitted)-Date.parse(s.assessments.post.submitted))/86400000;persist();return true;}
function studyExport(){const s=learningState();return {schema:'prompt-lab-study-1',version:LEARNING_VERSION,exported:stamp(),scope:'형식 지시 준수 판단·설계. 학습효과 미입증',order:s.order,preDecision:s.preDecision||null,assessments:s.assessments,ratings:s.ratings||[],exposures:s.exposures,lessons:s.lessons,scoring:{objectiveMax:6,artifactMax:8,artifact:'독립 검토자가 채점. 자동 점수 없음',formEquivalence:'미검증'},notes:'시작~제출 간격은 휴식 포함 경과 시간이며 활동 시간이 아닙니다. 개인 변화는 인과 효과가 아닙니다.'};}
function csvCell(v){let t=String(v??'');if(/^[=+\-@\t\r]/.test(t))t="'"+t;return '"'+t.replace(/"/g,'""')+'"';}
function studyCSV(){const rows=[['version','phase','form','item','skill','answer_index','correct','started','submitted','elapsed_minutes_including_breaks','delay_days','help','flags']];Object.entries(learningState().assessments).forEach(([k,e])=>{if(!e.submitted)return;EXAMS[e.form].forEach(q=>rows.push([LEARNING_VERSION,k,e.form,q.id,SKILLS[q.skill],e.answers[q.id],e.answers[q.id]===q.key?1:0,e.started,e.submitted,((Date.parse(e.submitted)-Date.parse(e.started))/60000).toFixed(2),e.delayDays??'',e.help,e.flags.join('|')]));});return rows.map(r=>r.map(csvCell).join(',')).join('\r\n');}
function reviewPacket(){const s=learningState();return '# 직접 설계 독립 검토용\n\n채점자는 가능하면 학습 전/후와 학습 조건을 모르는 상태에서 답안을 평가하세요. 아래 문서에는 평가 시점을 숨겼습니다. A/B/C형 차이로 추정할 수 있어 완전한 눈가림은 아닙니다. 이름을 적지 마세요.\n\n## 공통 기준: 0~2점 × 4 = 8점\n'+RUBRIC.map(([t,d])=>`- ${t}: ${d}`).join('\n')+'\n\n두 검토자가 먼저 독립 채점하고 원점수를 남긴 뒤 불일치를 논의하세요. 자기평가 결과는 독립 평가로 보고하지 마세요.\n\n'+Object.values(s.assessments).filter(e=>e.submitted).sort((a,b)=>a.form.localeCompare(b.form)).map(e=>`## 답안 ${e.form}\n\n과제: ${PRODUCTIONS[e.form]}\n\n답안:\n${e.artifact}\n\n|항목|점수(0/1/2)|답안 근거|\n|---|---|---|\n${RUBRIC.map(([t])=>`|${t}|||`).join('\n')}\n\n검토자 코드: ____ / 합계: ____ / 의견: ____\n`).join('\n');}
function exportBackup(){download('prompt-lab-full-backup.json',JSON.stringify({schema:'prompt-lab-backup-3',exported:stamp(),state:saved},null,2),'application/json');}
function ratingError(r){if(!['self','independent'].includes(r.type)||!r.reviewer?.trim()||!['A','B','C'].includes(r.form))return '평가 종류·검토자 코드·답안형을 선택해 주세요.';if(!Array.isArray(r.scores)||r.scores.length!==4||r.scores.some(n=>!Number.isInteger(n)||n<0||n>2))return '네 기준 모두 0~2점으로 평가해 주세요.';if(!Array.isArray(r.evidence)||r.evidence.length!==4||r.evidence.some(t=>!t.trim()))return '각 점수의 근거를 답안에서 찾아 적어 주세요.';return '';}
function renderRatings(){const s=learningState(),submitted=Object.values(s.assessments).filter(e=>e.submitted);const panel=$('#ratings-panel');if(!panel)return;
 panel.innerHTML=`<h2>직접 쓴 답안 검토하기</h2><p>다른 사람에게 검토를 부탁하려면 위의 ‘작성 답안·채점표’를 전달하세요. 여기에는 검토받은 점수와 이유를 적습니다. 본인이 채점했거나 검토자가 학습 전후의 답안이라는 사실을 알고 있었다면, 그 점도 함께 적어 주세요.</p><details><summary>4개 기준과 0·1·2점의 의미</summary>${RUBRIC.map(([t,d])=>`<h3>${esc(t)}</h3><p>${esc(d)}</p>`).join('')}</details>${submitted.length?`<label class="field" for="rating-form">검토할 답안</label><select id="rating-form">${submitted.map(e=>`<option value="${e.form}">${e.form}형</option>`).join('')}</select><label class="field" for="rating-type">검토 방식</label><select id="rating-type"><option value="">선택하세요</option><option value="self">직접 채점</option><option value="independent">다른 사람의 채점 결과</option></select><label class="field" for="rating-reviewer">검토자 코드 · 실명 대신 R1 등</label><input id="rating-reviewer" type="text" maxlength="40">${RUBRIC.map(([t],i)=>`<label class="field" for="rating-${i}">${i+1}. ${esc(t)}</label><select id="rating-${i}"><option value="">점수 선택</option><option value="0">0점</option><option value="1">1점</option><option value="2">2점</option></select><label class="field" for="rating-evidence-${i}">점수의 근거</label><textarea id="rating-evidence-${i}" maxlength="3000" placeholder="점수를 준 이유를 적어 주세요. 답안의 해당 문장이나 빠뜨린 조건을 짚어 주면 좋습니다."></textarea>`).join('')}<button id="save-rating" class="primary">검토 기록 추가</button><p class="note">점수를 고칠 때는 새 기록을 추가해 주세요. 같은 사람이 같은 답안을 같은 방식으로 다시 평가했다면, 가장 최근 점수를 사용하고 이전 기록도 남겨 둡니다.</p>`:'<p>직접 설계 답안을 제출하면 검토 결과를 남길 수 있습니다.</p>'}<div id="rating-list">${(s.ratings||[]).length?`<div class="tablewrap"><table><thead><tr><th>답안</th><th>검토자</th><th>방식</th><th>점수 / 8</th><th>기록</th></tr></thead><tbody>${s.ratings.map((r,i)=>`<tr><td>${esc(r.form)}</td><td>${esc(r.reviewer)}</td><td>${r.type==='self'?'자기검토':'외부 검토'}</td><td>${r.scores.reduce((a,b)=>a+b,0)}</td><td>${i+1} · ${esc(new Date(r.at).toLocaleDateString('ko-KR'))}</td></tr>`).join('')}</tbody></table></div><p class="note">다른 사람이 채점했더라도 평가가 공정했는지, 평가자끼리 기준이 같았는지는 따로 확인해야 합니다. 자기 점수와 다른 사람이 준 점수는 평균 내지 말고 따로 봐 주세요.</p>`:''}</div>`;
 if($('#save-rating'))$('#save-rating').onclick=()=>{const r={form:$('#rating-form').value,type:$('#rating-type').value,reviewer:$('#rating-reviewer').value.trim(),scores:RUBRIC.map((_,i)=>$('#rating-'+i).value===''?null:Number($('#rating-'+i).value)),evidence:RUBRIC.map((_,i)=>$('#rating-evidence-'+i).value.trim()),at:stamp()};const err=ratingError(r);if(err){notify(err);return;}s.ratings=s.ratings||[];s.ratings.push(r);const stored=persist();renderRatings();notify(stored?'검토 기록을 추가했습니다. 평가 기록 JSON에도 포함됩니다.':'화면에 기록했지만 저장소가 제한됐습니다. 평가 기록 JSON을 내려받으세요.');};
}
function validateLearningBackup(data){
 if(data?.schema!=='prompt-lab-backup-3'||data.state?.learningV3?.version!==LEARNING_VERSION)throw Error('이 과정 버전의 전체 백업 파일이 아닙니다.');
 const v=data.state.learningV3;const obj=x=>x&&typeof x==='object'&&!Array.isArray(x);const str=(x,n=12000)=>typeof x==='string'&&x.length<=n;const date=x=>str(x,80)&&Number.isFinite(Date.parse(x));
 if(!obj(v.lessons)||!obj(v.assessments)||!Array.isArray(v.order)||!['AB','BA'].includes(v.order.join(''))||!date(v.created)||!Array.isArray(v.exposures)||!Array.isArray(v.events))throw Error('백업 구조가 올바르지 않습니다.');
 for(const [i,r] of Object.entries(v.lessons)){if(!/^[0-7]$/.test(i)||!obj(r)||!obj(r.answers)||!obj(r.fields)||!Array.isArray(r.evidence)||r.evidence.length!==3||r.evidence.some(t=>!str(t,3000))||!Array.isArray(r.history)||!Number.isInteger(r.step)||r.step<0||r.step>4||!date(r.started))throw Error('차시 기록이 올바르지 않습니다.');
 for(const [k,t] of Object.entries(r.fields))if(!['draft','final','reason','takeaway'].includes(k)||!str(t))throw Error('답안 필드가 올바르지 않습니다.');
 for(const [id,a] of Object.entries(r.answers)){const q=PRACTICE[+i].find(q=>q.id===id);if(!q||!obj(a)||a.selected!==undefined&&(!Number.isInteger(a.selected)||a.selected<0||a.selected>2)||a.attempts!==undefined&&(!Array.isArray(a.attempts)||a.attempts.some(t=>!Number.isInteger(t.choice)||t.choice<0||t.choice>2||!date(t.at))))throw Error('판단 기록이 올바르지 않습니다.');}
 if(r.firstDraft!==undefined&&!str(r.firstDraft))throw Error('초안이 올바르지 않습니다.');if(r.draftLocked&&!date(r.draftLocked)||r.completed&&!date(r.completed)||r.solutionViewed&&!date(r.solutionViewed))throw Error('차시 시간이 올바르지 않습니다.');
 for(const h of r.history)if(!obj(h)||!date(h.at)||!str(h.final)||!str(h.reason)||!Array.isArray(h.evidence)||h.evidence.length!==3||h.evidence.some(t=>!str(t,3000)))throw Error('수정 이력이 올바르지 않습니다.');}
 for(const [k,e] of Object.entries(v.assessments)){if(!['pre','post','delayed'].includes(k)||!obj(e)||e.form!==examForm(k,v)||!obj(e.answers)||!str(e.artifact)||!date(e.started)||!Number.isInteger(e.step)||e.step<0||e.step>6||!Array.isArray(e.flags)||e.flags.some(t=>!str(t,200)))throw Error('평가 기록이 올바르지 않습니다.');
 for(const [id,a] of Object.entries(e.answers))if(!EXAMS[e.form].some(q=>q.id===id)||!Number.isInteger(a)||a<0||a>2)throw Error('평가 답안이 올바르지 않습니다.');if(e.submitted&&(!date(e.submitted)||examSubmissionError(e)))throw Error('제출된 평가가 불완전합니다.');if(e.delayDays!==undefined&&(!Number.isFinite(e.delayDays)||e.delayDays<0))throw Error('평가 간격이 올바르지 않습니다.');}
 if(v.assessments.delayed&&!v.assessments.post?.submitted)throw Error('지연 평가에 필요한 사후 기록이 없습니다.');
 for(const e of v.exposures)if(!obj(e)||!date(e.at)||!Array.isArray(e.forms)||e.forms.some(f=>!['A','B','C'].includes(f)))throw Error('해설 노출 기록이 올바르지 않습니다.');
 if(v.ratings!==undefined){if(!Array.isArray(v.ratings))throw Error('검토 기록이 올바르지 않습니다.');for(const r of v.ratings)if(!obj(r)||!str(r.reviewer,40)||!Array.isArray(r.evidence)||r.evidence.some(t=>!str(t,3000))||ratingError(r)||!date(r.at)||!Object.values(v.assessments).some(e=>e.submitted&&e.form===r.form))throw Error('검토 기록이 올바르지 않습니다.');}
 for(const e of Object.values(v.assessments))if(e.optionOrders!==undefined){if(!obj(e.optionOrders))throw Error('선택지 순서가 올바르지 않습니다.');for(const q of EXAMS[e.form])if(!Array.isArray(e.optionOrders[q.id])||[...e.optionOrders[q.id]].sort().join('')!=='012')throw Error('선택지 순서가 올바르지 않습니다.');}
 // Keep only recognized keys; never merge untrusted prototype keys into app state.
 return JSON.parse(JSON.stringify(v),(key,value)=>['__proto__','constructor','prototype'].includes(key)?undefined:value);
}
async function restoreBackup(ev){const file=ev.target.files?.[0];if(!file)return;try{if(file.size>5000000)throw Error('백업은 5MB 이하만 불러올 수 있습니다.');const v=validateLearningBackup(JSON.parse(await file.text()));if(!confirm('현재 새 과정 기록을 백업 파일의 기록으로 교체할까요? 기존 기록을 먼저 백업하는 것이 좋습니다. 개편 전 기록은 유지합니다.'))return;saved.learningV3=v;lessonIndex=-1;examView=null;const stored=persist();renderCourse();notify(stored?'새 과정 기록을 복원했습니다.':'현재 화면에만 복원됐습니다. 저장이 제한되어 다시 백업해야 합니다.');}catch(e){notify('복원하지 않았습니다: '+e.message);}finally{ev.target.value='';}}
